para.example:
   Operatore di Aggiunta degli array


<?php
$a = array("a" => "mela", "b" => "banana");
$b = array("a" => "pera", "b" => "fragola", "c" => "ciliegia");

$c = $a + $b; // Unione di $a e $b
echo "Unione di \$a e \$b: \n";
var_dump($c);

$c = $b + $a; // Unione di $b e $a
echo "Unione di \$b e \$a: \n";
var_dump($c);

$a += $b; // Unione di $a += $b è $a e $b
echo "Unione di \$a += \$b: \n";
var_dump($a);
?>


   &example.outputs;


Unione di $a e $b:
array(3) {
  ["a"]=>
  string(4) "mela"
  ["b"]=>
  string(6) "banana"
  ["c"]=>
  string(8) "ciliegia"
}
Unione di $b e $a:
array(3) {
  ["a"]=>
  string(4) "pera"
  ["b"]=>
  string(7) "fragola"
  ["c"]=>
  string(8) "ciliegia"
}
Unione di $a += $b:
array(3) {
  ["a"]=>
  string(4) "mela"
  ["b"]=>
  string(6) "banana"
  ["c"]=>
  string(8) "ciliegia"
}

